      "path": "src/state.ts",
      "content": "/**\n * RoundTable durable state: atomic file persistence under\n * `<workspace>/<stateDir>/<meetingId>/` with per-meeting process-local locks.\n *\n * - `meeting.json`     — the Meeting record (nodes, edges, decisions, budget).\n * - `transcript.jsonl` — append-only utterance log (torn-tail tolerant on read).\n * - `review.json`      — 针锋相对评审记录（议题/方案/观点/支持标记）。\n * - `user-actions.jsonl` — UI 行为记录（主持人下轮执行）。\n * - `kb-digest.json`   — 知识库摘要缓存（C2：命中即免去重读）。\n * @module dsh-plugin-roundtable/state\n */\n\nimport { appendFile, mkdir, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises'\nimport { randomUUID } from 'node:crypto'\nimport { dirname, join } from 'node:path'\nimport type { FeedbackEntry, KbDigestEntry, KbDigestFile, Meeting, MeetingUtterance, ReviewRecord, UserAction } from './types.ts'\n\n/** Stable directory id from a display name (keeps CJK, lowercases latin). */\nexport function sanitizeKey(value: string): string {\n  const cleaned = value.trim().toLowerCase().replace(/[^a-z0-9\\u4e00-\\u9fff]+/g, '-').replace(/^-+|-+$/g, '')\n  return cleaned === '' ? 'meeting' : cleaned\n}\n\n/** Process-local mutex chain keyed by an arbitrary lock key. */\nconst locks = new Map<string, Promise<unknown>>()\n\n/** Serialize async operations sharing one key inside this process. */\nexport async function withMeetingLock<T>(key: string, operation: () => Promise<T>): Promise<T> {\n  const previous = locks.get(key) ?? Promise.resolve()\n  const current = previous.then(operation, operation)\n  locks.set(key, current.then(() => undefined, () => undefined))\n  return current\n}\n\n/** Absolute state root under a workspace. */\nexport function stateRootOf(workspace: string, stateDir: string): string {\n  return join(workspace, stateDir)\n}\n\n/** Absolute directory of one meeting. */\nexport function meetingDirOf(stateRoot: string, meetingId: string): string {\n  return join(stateRoot, meetingId)\n}\n\n/**\n * Drop every persisted record belonging to one meeting directory.\n *\n * `roundtable_create` reuses the id of a finished meeting (the id IS the\n * sanitized name), and while `meeting.json` gets rewritten, `transcript.jsonl`\n * is append-only and `review.json` / `user-actions.jsonl` / `export.md` /\n * `kb-digest.json` simply stay behind. Without this reset a brand-new meeting\n * inherits the previous one's utterances and review verbatim: the user is shown\n * a review window for a plan that belongs to an entirely different meeting and\n * is asked to endorse or reject flaws of a plan that is not the one on the\n * table (P3).\n *\n * Idempotent — a missing directory is not an error.\n */\nexport async function resetMeetingDirectory(stateRoot: string, meetingId: string): Promise<void> {\n  await rm(meetingDirOf(stateRoot, meetingId), { recursive: true, force: true })\n}\n\n/** Cached host atomic writer: `null` = not resolved yet, `undefined` = unavailable. */\nlet hostAtomicWriter: ((file: string, text: string) => Promise<void>) | undefined | null = null\n\n/**\n * Resolve the host's atomic writer **without making it a load gate**.\n *\n * A static import would mean a composition that lacks\n * `@deepseek-ai/dsh-atomic-write` fails to load this whole module — the same\n * \"optional capability became a hard gate\" failure v0.2.36 fixed for cordis\n * `inject`. So it is resolved once, lazily, and absence falls back to the local\n * implementation below.\n */\nasync function resolveHostWriter(): Promise<((file: string, text: string) => Promise<void>) | undefined> {\n  if (hostAtomicWriter !== null) return hostAtomicWriter\n  try {\n    const host = await import('@deepseek-ai/dsh-atomic-write') as {\n      writeFileAtomic?: (file: string, content: string, options: { mode: number }) => Promise<void>\n    }\n    const write = host.writeFileAtomic\n    hostAtomicWriter = typeof write === 'function'\n      ? (file: string, text: string) => write(file, text, { mode: 0o644 })\n      : undefined\n  } catch {\n    hostAtomicWriter = undefined\n  }\n  return hostAtomicWriter\n}\n\n/**\n * Atomically publish a UTF-8 text file.\n *\n * Prefers the host's `@deepseek-ai/dsh-atomic-write`: same-directory\n * random-suffix temp + rename, plus the bounded retry for transient Windows\n * `EACCES`/`EBUSY`/`EPERM` rename failures that our hand-rolled version lacked —\n * it moved the temp aside as `.stale-*` and threw, so **that write was simply\n * lost**. The host version removes its temp and rethrows instead.\n *\n * When the host does not provide that package, the local fallback keeps every\n * state write working (same tmp + rename, minus the Windows retry) rather than\n * failing the whole plugin.\n */\nexport async function writeTextAtomic(file: string, text: string): Promise<void> {\n  const hostWrite = await resolveHostWriter()\n  if (hostWrite !== undefined) {\n    await hostWrite(file, text)\n    return\n  }\n  const tmp = join(dirname(file), `.${randomUUID()}.tmp`)\n  await writeFile(tmp, text, 'utf8')\n  await rename(tmp, file)\n}\n\n/** Atomically publish a JSON file (same-directory tmp + rename). */\nasync function writeJsonAtomic(file: string, value: unknown): Promise<void> {\n  await writeTextAtomic(file, JSON.stringify(value, null, 2))\n}\n\n/** Lock key serializing append (UI) against clear (captain) for one meeting's\n *  `user-actions.jsonl`. Without it a clear could rename over a line the UI\n *  was midway through appending, orphaning a user action (A2). */\nfunction userActionsLockKey(stateRoot: string, meetingId: string): string {\n  return `user-actions:${stateRoot}:${meetingId}`\n}\n\n/** Read one meeting record; undefined when absent.\n *\n *  与 {@link readReview} 对齐：读出来的记录一律先过 {@link normalizeMeeting}\n *  升级到当前 schema 版本。v0.2.36 之前这里是全插件唯一的「裸\n *  `JSON.parse(...) as Meeting`」——形状一变老会议就静默读坏，而且没有任何\n *  版本号可供分支。 */\nexport async function readMeeting(stateRoot: string, meetingId: string): Promise<Meeting | undefined> {\n  try {\n    const raw = await readFile(join(stateRoot, meetingId, 'meeting.json'), 'utf8')\n    return normalizeMeeting(JSON.parse(raw) as Meeting)\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined\n    throw error\n  }\n}\n\n/** Persist one meeting record (atomic). 写入前同样过一遍 normalize：这样\n *  「读时升级 + 下次写入顺带落盘」形成一个闭环，老文件不会永远停在旧版本。 */\nexport async function writeMeeting(stateRoot: string, meeting: Meeting): Promise<void> {\n  const dir = meetingDirOf(stateRoot, meeting.id)\n  await mkdir(dir, { recursive: true })\n  const normalized = normalizeMeeting(meeting)\n  normalized.updatedAt = Date.now()\n  await writeJsonAtomic(join(dir, 'meeting.json'), normalized)\n}\n\n/* ------------------------------------------------------------------ *\n * meeting.json 的 schema 版本与迁移通道\n *  与 review.json 的 normalizeReview 同款设计，但写成「版本 → 迁移函数」\n *  的表，因为 meeting.json 是本插件最核心的持久化文件，可见的版本会更多。\n * ------------------------------------------------------------------ */\n\n/** 当前 `meeting.json` 的形状版本。加字段/改语义时递增，并在\n *  {@link MEETING_MIGRATIONS} 补一条从「前一版」升上来的函数。 */\nexport const CURRENT_MEETING_SCHEMA_VERSION = 1\n\n/**\n * 相邻版本迁移表：键 = 源版本，值 = 把该版本升到「源版本 + 1」的函数。\n *\n * 当前 1 就是最新版，所以表为空——**这不是占位符**：把机制先建起来，是为了\n * 让下一次改形状时只需要「加一条函数 + 递增常量」，而不是像 review.json 那样\n * 等到不得不迁移时才回头补一套。\n */\nconst MEETING_MIGRATIONS: Readonly<Record<number, (meeting: Meeting) => Meeting>> = {}\n\n/** 每个会话只播报一次迁移告警，避免 1 秒轮询的快照把日志刷爆。 */\nconst notifiedMeetingMigrations = new Set<string>()\n\n/** 把「字段缺失/类型不符」的最小集合补成合法缺省值（幂等）。\n *\n *  只处理**不改语义**的兼容补齐，绝不猜测用户的意图，也绝不让缺失字段变成\n *  `undefined` 混进后续计算（那正是「静默读坏」的样子）。 */\nfunction withMeetingDefaults(meeting: Meeting): Meeting {\n  if (!Array.isArray(meeting.nodes)) meeting.nodes = []\n  if (!Array.isArray(meeting.edges)) meeting.edges = []\n  if (!Array.isArray(meeting.decisions)) meeting.decisions = []\n  if (typeof meeting.round !== 'number' || !Number.isFinite(meeting.round)) meeting.round = 0\n  if (typeof meeting.charter !== 'string') meeting.charter = ''\n  const budget = meeting.budget as Partial<Meeting['budget']> | undefined\n  meeting.budget = {\n    maxRounds: typeof budget?.maxRounds === 'number' ? budget.maxRounds : 10,\n    maxTokens: typeof budget?.maxTokens === 'number' ? budget.maxTokens : 200000,\n    usedRounds: typeof budget?.usedRounds === 'number' ? budget.usedRounds : 0,\n    usedTokens: typeof budget?.usedTokens === 'number' ? budget.usedTokens : 0,\n    ...(typeof budget?.usedTokensReal === 'number' ? { usedTokensReal: budget.usedTokensReal } : {}),\n  }\n  return meeting\n}\n\n/**\n * Idempotently upgrade one meeting record to\n * {@link CURRENT_MEETING_SCHEMA_VERSION}（**内存内**，不写回；下次\n * {@link writeMeeting} 落盘时顺带升级）。\n *\n * 缺失 `schemaVersion` 视为 1（v0.2.36 及之前的文件都是这个形状），然后\n * 依次跑迁移表。三条防御：\n *   - 迁移函数抛错 → 保留原记录并告警，**绝不让读会议失败**（读不出来比读得\n *     不完美严重得多，那会让整场会议从界面上消失）；\n *   - 版本高于当前（用户从新版本回退到老版本）→ 原样返回并告警，不做降级\n *     猜测；\n *   - 版本非法（非整数 / < 1）→ 归一到 1 再走迁移。\n */\nexport function normalizeMeeting(meeting: Meeting): Meeting {\n  const declared = meeting.schemaVersion\n  const from = typeof declared === 'number' && Number.isInteger(declared) && declared >= 1 ? declared : 1\n  if (declared !== from) meeting.schemaVersion = from\n\n  if (from > CURRENT_MEETING_SCHEMA_VERSION) {\n    const key = `future:${meeting.id}:${from}`\n    if (!notifiedMeetingMigrations.has(key)) {\n      notifiedMeetingMigrations.add(key)\n      console.warn(\n        `[roundtable] meeting \"${meeting.id}\" was written by a newer plugin (schemaVersion ${from} > ${CURRENT_MEETING_SCHEMA_VERSION}); reading it as-is`,\n      )\n    }\n    return withMeetingDefaults(meeting)\n  }\n\n  let current = meeting\n  let migrated = false\n  for (let version = from; version < CURRENT_MEETING_SCHEMA_VERSION; version += 1) {\n    const step = MEETING_MIGRATIONS[version]\n    if (step === undefined) continue\n    try {\n      current = step(current)\n      migrated = true\n    } catch (error: unknown) {\n      // 迁移失败必须降级为「原样读」，不能让整场会议读不出来。\n      const key = `failed:${meeting.id}:${version}`\n      if (!notifiedMeetingMigrations.has(key)) {\n        notifiedMeetingMigrations.add(key)\n        console.warn(\n          `[roundtable] meeting \"${meeting.id}\" schema migration ${version}→${version + 1} failed:`,\n          error instanceof Error ? error.message : String(error),\n        )\n      }\n      break\n    }\n  }\n\n  current = withMeetingDefaults(current)\n  if (migrated || from < CURRENT_MEETING_SCHEMA_VERSION || declared !== from) {\n    current.schemaVersion = CURRENT_MEETING_SCHEMA_VERSION\n  }\n  return current\n}\n\n/** Lock key serializing transcript appends for one meeting (A3).\n *\n *  `O_APPEND` already makes a single short line atomic, but this closes the\n *  remaining interleaving window (long lines, lifecycle-event races) so two\n *  utterances can never end up written into each other. */\nfunction transcriptLockKey(stateRoot: string, meetingId: string): string {\n  return `transcript:${stateRoot}:${meetingId}`\n}\n\n/** Append one utterance to the meeting transcript (JSONL). */\nexport async function appendUtterance(stateRoot: string, meetingId: string, utterance: MeetingUtterance): Promise<void> {\n  await withMeetingLock(transcriptLockKey(stateRoot, meetingId), async () => {\n    const dir = meetingDirOf(stateRoot, meetingId)\n    await mkdir(dir, { recursive: true })\n    await appendFile(join(dir, 'transcript.jsonl'), JSON.stringify(utterance) + '\\n', 'utf8')\n  })\n}\n\n/** Read the full transcript, skipping torn tails and malformed lines. */\nexport async function readTranscript(stateRoot: string, meetingId: string): Promise<MeetingUtterance[]> {\n  try {\n    const raw = await readFile(join(stateRoot, meetingId, 'transcript.jsonl'), 'utf8')\n    const out: MeetingUtterance[] = []\n    for (const line of raw.split(/\\r?\\n/)) {\n      if (line.trim() === '') continue\n      try {\n        out.push(JSON.parse(line) as MeetingUtterance)\n      } catch {\n        // Torn or malformed tail line: ignore and keep reading.\n      }\n    }\n    return out\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []\n    throw error\n  }\n}\n\n/** List every meeting id under a state root (missing root = empty). */\nexport async function listMeetings(stateRoot: string): Promise<string[]> {\n  try {\n    const entries = await readdir(stateRoot, { withFileTypes: true })\n    return entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name)\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []\n    throw error\n  }\n}\n\n/** Append one user action to the meeting's `user-actions.jsonl` (JSONL).\n *  Serialized against {@link clearUserActions} so an append can never race a\n *  clear (A2). A single short line stays atomic under `O_APPEND`. */\nexport async function appendUserAction(stateRoot: string, meetingId: string, action: UserAction): Promise<void> {\n  await withMeetingLock(userActionsLockKey(stateRoot, meetingId), async () => {\n    const dir = meetingDirOf(stateRoot, meetingId)\n    await mkdir(dir, { recursive: true })\n    await appendFile(join(dir, 'user-actions.jsonl'), JSON.stringify(action) + '\\n', 'utf8')\n  })\n}\n\n/** Result of parsing `user-actions.jsonl`: the usable actions plus the number\n *  of lines that were NOT valid JSON. The count exists so a torn tail is\n *  *reported* instead of silently vanishing (A2). */\nexport interface UserActionsReport {\n  actions: UserAction[]\n  /** Unparseable lines (torn tail / half-written JSON) that were dropped. */\n  malformed: number\n}\n\n/** Read every pending user action, counting rather than hiding bad lines. */\nexport async function readUserActionsReport(stateRoot: string, meetingId: string): Promise<UserActionsReport> {\n  try {\n    const raw = await readFile(join(stateRoot, meetingId, 'user-actions.jsonl'), 'utf8')\n    const actions: UserAction[] = []\n    let malformed = 0\n    for (const line of raw.split(/\\r?\\n/)) {\n      if (line.trim() === '') continue\n      try {\n        actions.push(JSON.parse(line) as UserAction)\n      } catch {\n        malformed += 1\n      }\n    }\n    return { actions, malformed }\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return { actions: [], malformed: 0 }\n    throw error\n  }\n}\n\n/** Read every pending user action, skipping torn tails and malformed lines. */\nexport async function readUserActions(stateRoot: string, meetingId: string): Promise<UserAction[]> {\n  return (await readUserActionsReport(stateRoot, meetingId)).actions\n}\n\n/**\n * Clear every pending user action, atomically and under the append lock.\n *\n * Returns both how many actions were cleared and how many unparseable lines\n * were dropped, so the captain can tell the user the truth about a loss\n * instead of reporting a clean sweep that never happened (A2).\n */\nexport async function clearUserActions(\n  stateRoot: string,\n  meetingId: string,\n): Promise<{ cleared: number; malformed: number }> {\n  return withMeetingLock(userActionsLockKey(stateRoot, meetingId), async () => {\n    const dir = meetingDirOf(stateRoot, meetingId)\n    await mkdir(dir, { recursive: true })\n    const { actions, malformed } = await readUserActionsReport(stateRoot, meetingId)\n    await writeTextAtomic(join(dir, 'user-actions.jsonl'), '')\n    return { cleared: actions.length, malformed }\n  })\n}\n\n/** Read the 针锋相对 review record; undefined when absent. Migrates old\n *  schemaVersion-1 records (endorsed boolean, whole-utterance viewpoints) to\n *  the current shape in memory — idempotent, no write-back (next writeReview\n *  persists the upgraded shape). */\nexport async function readReview(stateRoot: string, meetingId: string): Promise<ReviewRecord | undefined> {\n  try {\n    const raw = await readFile(join(meetingDirOf(stateRoot, meetingId), 'review.json'), 'utf8')\n    return normalizeReview(JSON.parse(raw) as ReviewRecord)\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined\n    throw error\n  }\n}\n\n/** Idempotently upgrade a review record to schemaVersion 2 (in-memory only).\n *  v1: viewpoint = {id(utterance id), nodeKey, content, endorsed, ts} →\n *  v2: {id: `${utteranceId}#${seq}`, utteranceId, nodeKey, content,\n *       status, quote?, dimension, ts, seq}. v2 records created before the\n *  C3 复审轮次 fields existed are given reviewPass=1 / maxReviewPass=3. */\nexport function normalizeReview(review: ReviewRecord): ReviewRecord {\n  const base = (review.schemaVersion ?? 1) === 2 ? review : undefined\n  if (base !== undefined) {\n    if (typeof review.reviewPass !== 'number' || review.reviewPass < 1) review.reviewPass = 1\n    if (typeof review.maxReviewPass !== 'number' || review.maxReviewPass < 1) review.maxReviewPass = 3\n    if (!Array.isArray(review.history)) review.history = []\n    return review\n  }\n  const migrated: ReviewRecord = {\n    meetingId: review.meetingId,\n    question: review.question,\n    plan: review.plan,\n    status: review.status,\n    reviewPass: 1,\n    maxReviewPass: 3,\n    history: [],\n    schemaVersion: 2,\n    viewpoints: review.viewpoints.map((viewpoint) => {\n      const legacy = viewpoint as unknown as {\n        id?: unknown\n        nodeKey?: unknown\n        content?: unknown\n        endorsed?: unknown\n        ts?: unknown\n      }\n      const utteranceId = typeof legacy.id === 'string' ? legacy.id : ''\n      const content = typeof legacy.content === 'string' ? legacy.content : ''\n      return {\n        id: `${utteranceId}#0`,\n        utteranceId,\n        nodeKey: typeof legacy.nodeKey === 'string' ? legacy.nodeKey : '',\n        content,\n        status: legacy.endorsed === true ? 'endorsed' : 'pending',\n        dimension: '其他',\n        ts: typeof legacy.ts === 'number' ? legacy.ts : Date.now(),\n        seq: 0,\n      }\n    }),\n    startedAt: review.startedAt,\n    updatedAt: review.updatedAt,\n  }\n  return migrated\n}\n\n/** Persist the review record (atomic). */\nexport async function writeReview(stateRoot: string, meetingId: string, review: ReviewRecord): Promise<void> {\n  const dir = meetingDirOf(stateRoot, meetingId)\n  await mkdir(dir, { recursive: true })\n  review.updatedAt = Date.now()\n  await writeJsonAtomic(join(dir, 'review.json'), review)\n}\n\n/** Set one viewpoint's three-state status (pending/endorsed/rejected);\n *  when rejecting, the caller must supply a non-empty reason (C2).\n *  Returns true when the value changed. */\nexport async function setViewpointStatus(\n  stateRoot: string,\n  meetingId: string,\n  viewpointId: string,\n  status: 'pending' | 'endorsed' | 'rejected',\n  rejectReason?: string,\n): Promise<boolean> {\n  const review = await readReview(stateRoot, meetingId)\n  if (review === undefined) return false\n  const viewpoint = review.viewpoints.find((candidate) => candidate.id === viewpointId)\n  if (viewpoint === undefined || viewpoint.status === status) return false\n  if (status === 'rejected') {\n    const reason = rejectReason?.trim() ?? ''\n    if (reason === '') throw new Error('rejecting a viewpoint requires a non-empty reject_reason (驳回必填理由)')\n    viewpoint.rejectReason = reason.slice(0, 500)\n  }\n  viewpoint.status = status\n  await writeReview(stateRoot, meetingId, review)\n  return true\n}\n\n/* ------------------------------------------------------------------ *\n * 知识库摘要缓存（C2）：<meetingDir>/kb-digest.json\n * 独立文件（沿用 review.json 的同级惯例），避免 meeting.json 竞态。\n * ------------------------------------------------------------------ */\n\n/** Structural guard: only well-formed entries survive a hand-edited cache file. */\nfunction isKbDigestEntry(value: unknown): value is KbDigestEntry {\n  if (value === null || typeof value !== 'object') return false\n  const entry = value as Partial<KbDigestEntry>\n  return typeof entry.path === 'string' && entry.path !== ''\n    && typeof entry.size === 'number'\n    && typeof entry.mtimeMs === 'number'\n    && typeof entry.digest === 'string'\n    && typeof entry.ts === 'number'\n}\n\n/** Read the knowledge-base digest cache.\n *\n *  A missing OR corrupt file reads as empty: a bad cache must never block a\n *  meeting — the worst case is that the captain re-reads a file, which is\n *  exactly the behaviour that existed before the cache. */\nexport async function readKbDigest(stateRoot: string, meetingId: string): Promise<KbDigestFile> {\n  const empty: KbDigestFile = { meetingId, entries: [], updatedAt: 0 }\n  let raw: string\n  try {\n    raw = await readFile(join(meetingDirOf(stateRoot, meetingId), 'kb-digest.json'), 'utf8')\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return empty\n    throw error\n  }\n  try {\n    const parsed = JSON.parse(raw) as Partial<KbDigestFile>\n    return {\n      meetingId,\n      entries: Array.isArray(parsed.entries) ? parsed.entries.filter(isKbDigestEntry) : [],\n      updatedAt: typeof parsed.updatedAt === 'number' ? parsed.updatedAt : 0,\n    }\n  } catch {\n    return empty\n  }\n}\n\n/** Persist the knowledge-base digest cache (atomic). */\nexport async function writeKbDigest(\n  stateRoot: string,\n  meetingId: string,\n  entries: readonly KbDigestEntry[],\n): Promise<void> {\n  const dir = meetingDirOf(stateRoot, meetingId)\n  await mkdir(dir, { recursive: true })\n  const file: KbDigestFile = { meetingId, entries: [...entries], updatedAt: Date.now() }\n  await writeJsonAtomic(join(dir, 'kb-digest.json'), file)\n}\n\n/* ------------------------------------------------------------------ *\n * 工作区级匿名反馈（E1/E3）：feedback.jsonl 放在 stateRoot 下（跨会议聚合）。\n * 只记录结构化使用事实 + 用户主动填写的一句说明，绝不记录对话内容。\n * ------------------------------------------------------------------ */\n\n/** Lock key serializing every `feedback.jsonl` writer of one workspace (P11).\n *\n *  The file is workspace-scoped, so a meeting-scoped lock is not enough: one\n *  meeting's \"clear then append\" used to rewrite the whole file while another\n *  meeting was appending, silently dropping that entry. */\nfunction feedbackLockKey(stateRoot: string): string {\n  return `feedback:${stateRoot}`\n}\n\n/** Append one feedback entry to `<stateRoot>/feedback.jsonl`. */\nexport async function appendFeedback(stateRoot: string, entry: FeedbackEntry): Promise<void> {\n  return withMeetingLock(feedbackLockKey(stateRoot), async () => {\n    await mkdir(stateRoot, { recursive: true })\n    await appendFile(join(stateRoot, 'feedback.jsonl'), JSON.stringify(entry) + '\\n', 'utf8')\n  })\n}\n\n/** Read every feedback entry (newest last), skipping torn tails. */\nexport async function readFeedback(stateRoot: string): Promise<FeedbackEntry[]> {\n  try {\n    const raw = await readFile(join(stateRoot, 'feedback.jsonl'), 'utf8')\n    const out: FeedbackEntry[] = []\n    for (const line of raw.split(/\\r?\\n/)) {\n      if (line.trim() === '') continue\n      try {\n        out.push(JSON.parse(line) as FeedbackEntry)\n      } catch {\n        // Torn or malformed tail line: ignore and keep reading.\n      }\n    }\n    return out\n  } catch (error: unknown) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []\n    throw error\n  }\n}\n\n/** Remove every feedback entry for one meeting id (dedupe); returns count removed. */\nexport async function clearFeedbackForMeeting(stateRoot: string, meetingId: string): Promise<number> {\n  return withMeetingLock(feedbackLockKey(stateRoot), async () => {\n    const before = await readFeedback(stateRoot)\n    const remaining = before.filter((entry) => entry.meetingId !== meetingId)\n    await writeTextAtomic(\n      join(stateRoot, 'feedback.jsonl'),\n      remaining.map((entry) => JSON.stringify(entry)).join('\\n') + (remaining.length > 0 ? '\\n' : ''),\n    )\n    return before.length - remaining.length\n  })\n}\n\n/** Remove every feedback entry; returns how many were dropped. */\nexport async function clearFeedback(stateRoot: string): Promise<number> {\n  return withMeetingLock(feedbackLockKey(stateRoot), async () => {\n    const before = await readFeedback(stateRoot)\n    await writeTextAtomic(join(stateRoot, 'feedback.jsonl'), '')\n    return before.length\n  })\n}\n"
    },
    {
      "path": "src/rpc.ts",
      "content": "/**\n * RPC handlers for the browser topology tab:\n *   - `roundtable/prefs.get`   → { defaultMode, maxRounds, maxTokens }\n *   - `roundtable/prefs.set`   → persist user preferences\n *   - `roundtable/edge.set`    → flip one edge's direction (UI right-click menu)\n *   - `roundtable/edge.add`    → drag-to-connect a new channel\n *   - `roundtable/edge.remove` → remove an edge\n *\n * Registered on the host through `ctx.inject(['connection'])` on the plugin's\n * OWN RPC channel `/roundtable` (NOT the shared `/api` one). The `/api`\n * channel is a single-interceptor shared channel owned by dsh-api-gateway, so\n * registering a second `intercept('/api')` here throws\n * \"shared RPC channel /api already has an interceptor\" and silently drops\n * every roundtable RPC — which is exactly why drag-to-connect looked dead for\n * both removed AND active nodes. Using `rpc.handle('/roundtable', ...)` gives\n * this plugin its own prefix-routed channel, mirroring the ya-subagent plugin.\n * @module dsh-plugin-roundtable/rpc\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n// Value import triggers `declare module 'cordis'` merge for `ctx.connection`.\nimport type {} from '@deepseek-ai/dsh-client-connection'\n// Declaration merge only: makes ctx.llm visible for the model-list RPC.\nimport type {} from '@deepseek-ai/dsh-llm'\nimport { randomUUID } from 'node:crypto'\nimport { readdir, rm, stat } from 'node:fs/promises'\nimport { dirname, extname, isAbsolute, join } from 'node:path'\nimport type { EdgeDirection, FeedbackEntry, UserAction } from './types.ts'\n// 偏好形状、净化规则与自持久化存储都住在 preferences.ts：宿主 0.2.0-rc.2 把\n// `settings` 服务重构成 `SettingsForms`（投影 profile 配置），插件不再能注册\n// 自己的命名空间，因此偏好改为落 DSH home 下的 JSON 文件。\nimport {\n  ROLE_PRESET_MAX,\n  ROUNDTABLE_PANELS,\n  SQUAD_MAX,\n  SQUAD_MEMBER_MAX,\n  sanitizeHiddenPanels,\n  sanitizeRolePresets,\n  sanitizeSquads,\n  type PreferenceStore,\n  type RoundTablePreferences,\n} from './preferences.ts'\nimport { interruptNodeByParent } from './members.ts'\nimport {\n  appendFeedback,\n  appendUserAction,\n  clearFeedback,\n  clearFeedbackForMeeting,\n  meetingDirOf,\n  readFeedback,\n  readMeeting,\n  readReview,\n  readUserActions,\n  setViewpointStatus,\n  stateRootOf,\n  withMeetingLock,\n  writeMeeting,\n} from './state.ts'\nimport { buildCharter } from './charter.ts'\nimport { effectWithOptionalDisposer } from './harness-compat.ts'\n\n/** RPC result envelope (mirrors the apiproxy wire shape). */\nexport type RpcResult<T> =\n  | { ok: true; value: T; error?: never }\n  | { ok: false; error: { code: string; message: string; details?: unknown }; value?: never }\n\n/**\n * 偏好形状与净化规则住在 `preferences.ts`（那里的模块注释说明了原因：宿主\n * 0.2.0-rc.2 把 `settings` 服务重构成 `SettingsForms`，插件不再能注册自己的\n * 命名空间）。这里 re-export 只为不打断既有引用路径。\n */\nexport type { RoundTablePreferences }\n// 与旧版一致：净化函数与上限常量仍从 rpc.ts 可取（测试与工具都按这个路径导入）。\nexport {\n  ROLE_PRESET_MAX,\n  ROUNDTABLE_PANELS,\n  SQUAD_MAX,\n  SQUAD_MEMBER_MAX,\n  sanitizeHiddenPanels,\n  sanitizeRolePresets,\n  sanitizeSquads,\n}\n\n/** 自持久化偏好存储 + 会议 state 根，共享给工具与 RPC 两条执行路径。 */\nexport interface RoundTableRuntime {\n  /** 偏好读写（见 preferences.ts：宿主 settings 服务在 0.2.0-rc.2 已重构）。 */\n  prefs: PreferenceStore\n  stateDir: string\n}\n\n/**\n * Browser-facing POST route for this plugin's RPC.\n *\n * It mirrors the snapshot route's transport (the plugin's own `webServer`\n * registration) instead of relying on the host's generic connection channel,\n * which is what the client actually reaches.\n */\nexport const RPC_ROUTE = '/plugins/dsh-plugin-roundtable/rpc'\n\n/** One endpoint dispatch: `(endpoint, payload) => envelope`, never throws. */\nexport type RpcDispatch = (endpoint: string, payload: unknown) => Promise<RpcResult<unknown>>\n\nfunction ok<T>(value: T): RpcResult<T> {\n  return { ok: true, value }\n}\n\nfunction fail<T>(message: string): RpcResult<T> {\n  return { ok: false, error: { code: 'internal', message } }\n}\n\n/** Connection service slice used to register this plugin's own RPC channel. */\ninterface RpcConnection {\n  readonly rpc: {\n    /**\n     * 0.1.5-rc.1 起为两参签名：`handle(channel, handler) => disposer`。\n     * 0.1.1 时代的第三参 `{ authority }` 已被移除；实测运行时忽略多余实参，\n     * 因此本 shim 只保留真实形状，避免后人照抄不存在的选项。\n     */\n    readonly handle: (\n      channel: string,\n      handler: (endpoint: string, payload: unknown, signal: AbortSignal) => Promise<RpcResult<unknown>>,\n    ) => unknown  }\n}\n\n/** Run one meeting mutation under the meeting lock, resolving its state root first. */\nasync function withMeetingRpcLock<T>(\n  runtime: RoundTableRuntime,\n  meetingId: string,\n  operation: (stateRoot: string) => Promise<RpcResult<T>>,\n  options: { requireActive?: boolean } = {},\n): Promise<RpcResult<T>> {\n  const { workspaceOfMeeting } = await import('./edge-helper.ts')\n  const workspace = await workspaceOfMeeting(runtime.stateDir, meetingId)\n  if (workspace === undefined) return fail(`meeting \"${meetingId}\" not found in any workspace`)\n  const stateRoot = stateRootOf(workspace, runtime.stateDir)\n  return withMeetingLock(`meeting:${stateRoot}:${meetingId}`, async () => {\n    if (options.requireActive === true) {\n      // P10（第 2 批）：工具侧一直有 `assertUsable` 闸门，RPC 侧却完全没有状态机\n      // 校验 —— 已结束会议的拓扑与知识库还能被改（导出物与快照随即不一致），而\n      // 给已结束会议排的专家操作永远不会有人执行，只能变成孤儿记录挂在 UI 上。\n      const meeting = await readMeeting(stateRoot, meetingId)\n      if (meeting !== undefined && (meeting.status === 'ended' || meeting.status === 'archived')) {\n        return fail<T>(`meeting \"${meetingId}\" has ended — its topology is read-only`)\n      }\n    }\n    return operation(stateRoot)\n  })\n}\n\n/** 观点三态写入（V0.2.2）。幂等；状态变化时写结构化 user-action（V2 回写负载）。\n *  驳回必须附理由（C2），由 setViewpointStatus 强制非空。\n *  P1 务实降级：connection 通道不暴露调用者 session 身份（handler 仅\n *  endpoint/payload/signal），无法做 captainSessionId 校验——以「会议归属\n *  校验（withMeetingRpcLock）+ 状态机校验（reviewing 阶段拒绝）」作为防线。 */\nasync function applyViewpointStatus(\n  runtime: RoundTableRuntime,\n  meetingId: string,\n  viewpointId: string,\n  status: 'pending' | 'endorsed' | 'rejected',\n  rejectReason?: string,\n): Promise<RpcResult<{ changed: boolean; status: string }>> {\n  return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n    const review = await readReview(stateRoot, meetingId)\n    if (review === undefined) return fail(`no review in progress for meeting \"${meetingId}\"`)\n    const viewpoint = review.viewpoints.find((candidate) => candidate.id === viewpointId)\n    if (viewpoint === undefined) return fail(`viewpoint \"${viewpointId}\" not found`)\n    if (review.status === 'reviewing') {\n      return fail('review is still collecting viewpoints — call roundtable_collect_review before endorsing or rejecting')\n    }\n    if (review.status === 'done') {\n      return fail('this review pass is finished — start a new pass (roundtable_start_review) to re-review')\n    }\n    let changed: boolean\n    try {\n      changed = await setViewpointStatus(stateRoot, meetingId, viewpointId, status, rejectReason)\n    } catch (error) {\n      return fail((error as Error).message)\n    }\n    if (changed && status !== 'pending') {\n      const label = status === 'endorsed' ? '用户认定缺陷' : '用户驳回观点'\n      const reasonText = status === 'rejected' && rejectReason !== undefined && rejectReason.trim() !== ''\n        ? `；理由：${rejectReason.trim().replace(/\\s+/g, ' ').slice(0, 120)}`\n        : ''\n      await appendUserAction(stateRoot, meetingId, {\n        id: randomUUID(),\n        ts: Date.now(),\n        kind: 'other',\n        nodeKey: viewpoint.nodeKey,\n        // V2：回写负载升级为结构化行 id（utteranceId#seq），主持人据此精确回改。\n        text: `${label}（针锋相对评审 ${viewpoint.id}）${reasonText}：${viewpoint.content.replace(/\\s+/g, ' ').slice(0, 60)}`,\n      })\n    }\n    return ok({ changed, status })\n  })\n}\n\n/**\n * Register the RoundTable RPC handler.\n *\n * Two transports share ONE dispatch body, so the browser can reach the plugin\n * even when the host's generic `connection` channel is not mounted (or its\n * `/roundtable` prefix got dropped by a live plugin reload):\n *   1. the host `connection` RPC channel `/roundtable` (kept for compatibility);\n *   2. the plugin's own `webServer` POST route `<RPC_ROUTE>` — the same\n *      transport as the `/plugins/dsh-plugin-roundtable/state` snapshot route,\n *      which is what the browser actually uses.\n *\n * @returns the dispatch function, so the caller can mount it on a web route.\n */\nexport function registerRpc(ctx: Context, runtime: RoundTableRuntime): RpcDispatch {\n  const dispatch: RpcDispatch = async (endpoint, payload) => {\n    try {\n      switch (endpoint) {\n          case 'roundtable/prefs.get': {\n            const prefs = runtime.prefs.get()\n            return ok<RoundTablePreferences>({\n              defaultMode: prefs.defaultMode,\n              maxRounds: prefs.maxRounds,\n              maxTokens: prefs.maxTokens,\n              showAllMeetings: prefs.showAllMeetings,\n              expertMaxTokens: prefs.expertMaxTokens ?? 0,\n              expertMaxOpinions: prefs.expertMaxOpinions ?? 0,\n              feedbackEnabled: prefs.feedbackEnabled ?? true,\n              skillDelivery: prefs.skillDelivery === 'direct' ? 'direct' : 'relay',\n              hiddenPanels: sanitizeHiddenPanels(prefs.hiddenPanels),\n              legendHidden: prefs.legendHidden === true,\n              rolePresets: sanitizeRolePresets(prefs.rolePresets),\n              squads: sanitizeSquads(prefs.squads),\n            })\n          }\n          case 'roundtable/prefs.set': {\n            const patch = payload as Partial<RoundTablePreferences> | undefined\n            if (patch === undefined || typeof patch !== 'object' || patch === null) {\n              return fail('payload must be a preferences patch object')\n            }\n            // 写入前先净化：坏数据不落库（schemastery 不会替我们拦）。\n            // preferences.ts 的 normalizePreferences 同时承担\"只覆盖出现过的字段\"\n            // 这层语义 —— 与旧宿主 `SettingsScope.update(patch)` 的行为一致。\n            const sanitized: Record<string, unknown> = { ...patch }\n            if (patch.hiddenPanels !== undefined) sanitized.hiddenPanels = sanitizeHiddenPanels(patch.hiddenPanels)\n            if (patch.legendHidden !== undefined) sanitized.legendHidden = patch.legendHidden === true\n            if (patch.rolePresets !== undefined) sanitized.rolePresets = sanitizeRolePresets(patch.rolePresets)\n            if (patch.squads !== undefined) sanitized.squads = sanitizeSquads(patch.squads)\n            const next = await runtime.prefs.update(sanitized)\n            return ok<RoundTablePreferences>({\n              defaultMode: next.defaultMode,\n              maxRounds: next.maxRounds,\n              maxTokens: next.maxTokens,\n              showAllMeetings: next.showAllMeetings,\n              expertMaxTokens: next.expertMaxTokens ?? 0,\n              expertMaxOpinions: next.expertMaxOpinions ?? 0,\n              feedbackEnabled: next.feedbackEnabled ?? true,\n              skillDelivery: next.skillDelivery === 'direct' ? 'direct' : 'relay',\n              hiddenPanels: sanitizeHiddenPanels(next.hiddenPanels),\n              legendHidden: next.legendHidden === true,\n              rolePresets: sanitizeRolePresets(next.rolePresets),\n              squads: sanitizeSquads(next.squads),\n            })\n          }\n          case 'roundtable/edge.set': {\n            const body = payload as { meetingId?: unknown; edgeId?: unknown; direction?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const edgeId = typeof body?.edgeId === 'string' ? body.edgeId : ''\n            if (meetingId === '' || edgeId === '') return fail('payload must be { meetingId, edgeId, direction }')\n            const directionRaw = typeof body?.direction === 'string' ? body.direction : ''\n            if (directionRaw !== 'forward' && directionRaw !== 'bidirectional') {\n              return fail('direction must be \"forward\" or \"bidirectional\"')\n            }\n            const direction: EdgeDirection = directionRaw\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const meeting = await readMeeting(stateRoot, meetingId)\n              if (meeting === undefined) return fail<{ direction: string }>(`meeting \"${meetingId}\" not found`)\n              const edge = meeting.edges.find((candidate) => candidate.id === edgeId)\n              if (edge === undefined) return fail<{ direction: string }>(`edge \"${edgeId}\" not found`)\n              edge.direction = direction\n              meeting.charter = buildCharter(meeting)\n              await writeMeeting(stateRoot, meeting)\n              return ok<{ direction: string }>({ direction: edge.direction })\n            }, { requireActive: true })\n          }\n          case 'roundtable/edge.add': {\n            const body = payload as { meetingId?: unknown; from?: unknown; to?: unknown; direction?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const from = typeof body?.from === 'string' ? body.from.trim() : ''\n            const to = typeof body?.to === 'string' ? body.to.trim() : ''\n            if (meetingId === '' || from === '' || to === '') return fail('payload must be { meetingId, from, to, direction }')\n            const direction: EdgeDirection = body?.direction === 'bidirectional' ? 'bidirectional' : 'forward'\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const meeting = await readMeeting(stateRoot, meetingId)\n              if (meeting === undefined) return fail<Record<string, string>>(`meeting \"${meetingId}\" not found`)\n              const valid = (key: string): boolean => key === 'captain' || key === 'aggregator'\n                || meeting.nodes.some((node) => node.key === key && node.status !== 'removed')\n              if (!valid(from)) return fail<Record<string, string>>(`unknown endpoint \"${from}\"`)\n              if (!valid(to)) return fail<Record<string, string>>(`unknown endpoint \"${to}\"`)\n              if (from === to) return fail<Record<string, string>>('an edge cannot connect a participant to itself')\n              if (meeting.edges.some((edge) => edge.from === from && edge.to === to)) {\n                return fail<Record<string, string>>(`channel ${from} → ${to} already exists`)\n              }\n              const edge = { id: randomUUID(), from, to, direction, createdAt: Date.now() }\n              meeting.edges.push(edge)\n              meeting.charter = buildCharter(meeting)\n              await writeMeeting(stateRoot, meeting)\n              return ok({ edgeId: edge.id, from: edge.from, to: edge.to, direction: edge.direction })\n            }, { requireActive: true })\n          }\n          case 'roundtable/edge.remove': {\n            const body = payload as { meetingId?: unknown; edgeId?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const edgeId = typeof body?.edgeId === 'string' ? body.edgeId : ''\n            if (meetingId === '' || edgeId === '') return fail('payload must be { meetingId, edgeId }')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const meeting = await readMeeting(stateRoot, meetingId)\n              if (meeting === undefined) return fail<{ removed: boolean }>(`meeting \"${meetingId}\" not found`)\n              const before = meeting.edges.length\n              meeting.edges = meeting.edges.filter((edge) => edge.id !== edgeId)\n              meeting.charter = buildCharter(meeting)\n              await writeMeeting(stateRoot, meeting)\n              return ok({ removed: before !== meeting.edges.length })\n            }, { requireActive: true })\n          }\n          case 'roundtable/meeting.delete': {\n            const body = payload as { meetingId?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            if (meetingId === '') return fail('payload must be { meetingId }')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const meeting = await readMeeting(stateRoot, meetingId)\n              if (meeting === undefined) return ok({ deleted: false })\n              // Best-effort: interrupt the meeting's expert subagents first so\n              // no orphan keeps running after the meeting is gone. 优先用不依赖\n              // live 父 Agent 的入口 —— 删会议时队长常常已经不在线，而\n              // `agents.interrupt` 那时只是静默 no-op。\n              for (const node of meeting.nodes) {\n                if (node.id === '') continue\n                if (interruptNodeByParent(ctx, node.id, meeting.captainSessionId)) continue\n                const agents = (ctx as unknown as { agents?: { interrupt?: (id: string) => unknown } }).agents\n                try { agents?.interrupt?.(node.id) } catch { /* best-effort */ }\n              }\n              await rm(meetingDirOf(stateRoot, meetingId), { recursive: true, force: true })\n              return ok({ deleted: true })\n            })\n          }\n          case 'roundtable/user-actions.append': {\n            // The Web UI records an expert edit here instead of touching\n            // meeting state; the captain drains the file next round.\n            const body = payload as {\n              meetingId?: unknown\n              kind?: unknown\n              nodeKey?: unknown\n              role?: unknown\n              provider?: unknown\n              model?: unknown\n              text?: unknown\n            } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const kindRaw = typeof body?.kind === 'string' ? body.kind : ''\n            if (meetingId === '' || (kindRaw !== 'add-node' && kindRaw !== 'remove-node' && kindRaw !== 'kb-path' && kindRaw !== 'other')) {\n              return fail('payload must be { meetingId, kind, text } with kind in add-node|remove-node|kb-path|other')\n            }\n            const text = typeof body?.text === 'string' ? body.text.trim() : ''\n            if (text === '') return fail('payload must include a non-empty text sentence')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const action: UserAction = {\n                id: randomUUID(),\n                ts: Date.now(),\n                kind: kindRaw as UserAction['kind'],\n                nodeKey: typeof body?.nodeKey === 'string' && body.nodeKey.trim() !== '' ? body.nodeKey.trim() : undefined,\n                role: typeof body?.role === 'string' && body.role.trim() !== '' ? body.role.trim() : undefined,\n                provider: typeof body?.provider === 'string' && body.provider.trim() !== '' ? body.provider.trim() : undefined,\n                model: typeof body?.model === 'string' && body.model.trim() !== '' ? body.model.trim() : undefined,\n                text,\n              }\n              await appendUserAction(stateRoot, meetingId, action)\n              return ok({ id: action.id })\n            }, { requireActive: true })\n          }\n          case 'roundtable/user-actions.list': {\n            const body = payload as { meetingId?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            if (meetingId === '') return fail('payload must be { meetingId }')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              return ok<UserAction[]>(await readUserActions(stateRoot, meetingId))\n            })\n          }\n          case 'roundtable/models.list': {\n            // Model dropdown for the expert-management UI: every registered\n            // provider route plus the models it advertises (advisory catalog).\n            const llm = ctx.get('llm') as\n              | {\n                  listProviders(): { id: string; name: string }[]\n                  listModels(provider: string): Promise<{ id: string; name: string }[]>\n                }\n              | undefined\n            if (llm === undefined) return ok({ providers: [] })\n            const providers: { id: string; name: string; models: { id: string; name: string }[] }[] = []\n            for (const provider of llm.listProviders()) {\n              let models: { id: string; name: string }[] = []\n              try {\n                models = await llm.listModels(provider.id)\n              } catch {\n                // A provider may fail to enumerate its catalog (e.g. missing\n                // key); it still appears with an empty model list so the UI\n                // stays usable.\n                models = []\n              }\n              providers.push({\n                id: provider.id,\n                name: provider.name,\n                models: models.map((model) => ({ id: model.id, name: model.name })),\n              })\n            }\n            return ok({ providers })\n          }\n          case 'roundtable/kb.path.set': {\n            // Knowledge-base path (阅览版): validated, stored on the meeting,\n            // never reads file contents. Relative paths resolve against the\n            // meeting's own workspace.\n            const body = payload as { meetingId?: unknown; path?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const raw = typeof body?.path === 'string' ? body.path.trim() : ''\n            if (meetingId === '' || raw === '') return fail('payload must be { meetingId, path }')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const meeting = await readMeeting(stateRoot, meetingId)\n              if (meeting === undefined) return fail<{ path: string }>(`meeting \"${meetingId}\" not found`)\n              const workspace = dirname(stateRoot)\n              const resolved = isAbsolute(raw) ? raw : join(workspace, raw)\n              let info\n              try {\n                info = await stat(resolved)\n              } catch {\n                return fail<{ path: string }>(`path not found or unreadable: ${resolved}`)\n              }\n              if (!info.isDirectory()) return fail<{ path: string }>(`path is not a directory: ${resolved}`)\n              meeting.kbPath = resolved\n              await writeMeeting(stateRoot, meeting)\n              return ok({ path: resolved })\n            }, { requireActive: true })\n          }\n          case 'roundtable/kb.list': {\n            // List the first level of the configured knowledge base (names,\n            // kinds, formats and sizes only — the browse-only contract).\n            const body = payload as { meetingId?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            if (meetingId === '') return fail('payload must be { meetingId }')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const meeting = await readMeeting(stateRoot, meetingId)\n              if (meeting === undefined) return fail<{ path: string }>(`meeting \"${meetingId}\" not found`)\n              const configured = meeting.kbPath ?? ''\n              if (configured === '') return ok({ path: '', configured: false, error: '', files: [] })\n              const listing = await listKbDirectory(configured)\n              return ok({ path: configured, configured: true, error: listing.error, files: listing.files })\n            })\n          }\n          case 'roundtable/review.get': {\n            // 针锋相对评审状态：前端评审弹窗轮询此接口。\n            const body = payload as { meetingId?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            if (meetingId === '') return fail('payload must be { meetingId }')\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              const review = await readReview(stateRoot, meetingId)\n              return ok({ review: review ?? null })\n            })\n          }\n          case 'roundtable/review.endorse': {\n            // V0.2.1 兼容别名：映射到三态 setStatus('endorsed')。\n            const body = payload as { meetingId?: unknown; viewpointId?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const viewpointId = typeof body?.viewpointId === 'string' ? body.viewpointId : ''\n            if (meetingId === '' || viewpointId === '') return fail('payload must be { meetingId, viewpointId }')\n            return applyViewpointStatus(runtime, meetingId, viewpointId, 'endorsed')\n          }\n          case 'roundtable/review.setStatus': {\n            // V0.2.2 三态：pending/endorsed/rejected 可互切（支持可取消、驳回）。\n            // 驳回必填理由（C2）：payload.reject_reason 非空，由 setViewpointStatus 强制。\n            const body = payload as { meetingId?: unknown; viewpointId?: unknown; status?: unknown; reject_reason?: unknown } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const viewpointId = typeof body?.viewpointId === 'string' ? body.viewpointId : ''\n            const status = body?.status\n            if (meetingId === '' || viewpointId === '') return fail('payload must be { meetingId, viewpointId, status }')\n            if (status !== 'pending' && status !== 'endorsed' && status !== 'rejected') {\n              return fail('status must be \"pending\" | \"endorsed\" | \"rejected\"')\n            }\n            const rejectReason = typeof body?.reject_reason === 'string' ? body.reject_reason : undefined\n            if (status === 'rejected' && (rejectReason === undefined || rejectReason.trim() === '')) {\n              return fail('rejecting a viewpoint requires a non-empty reject_reason (驳回必填理由)')\n            }\n            return applyViewpointStatus(runtime, meetingId, viewpointId, status, rejectReason)\n          }\n          case 'roundtable/feedback.append': {\n            // E1/E3 匿名反馈：前端在会议结束后询问，条目写工作区级 feedback.jsonl。\n            const body = payload as {\n              meetingId?: unknown\n              mode?: unknown\n              providers?: unknown\n              models?: unknown\n              usedRounds?: unknown\n              usedTokens?: unknown\n              rating?: unknown\n              note?: unknown\n            } | undefined\n            const meetingId = typeof body?.meetingId === 'string' ? body.meetingId : ''\n            const mode = typeof body?.mode === 'string' ? body.mode : ''\n            if (meetingId === '' || mode === '') return fail('payload must be { meetingId, mode, rating, ... }')\n            const ratingRaw = typeof body?.rating === 'string' ? body.rating : ''\n            if (ratingRaw !== 'good' && ratingRaw !== 'meh' && ratingRaw !== 'bad') {\n              return fail('rating must be \"good\" | \"meh\" | \"bad\"')\n            }\n            const asStringList = (value: unknown): string[] =>\n              Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string').slice(0, 20) : []\n            const note = typeof body?.note === 'string' ? body.note.trim().slice(0, 1000) : ''\n            const entry: FeedbackEntry = {\n              id: randomUUID(),\n              ts: Date.now(),\n              meetingId,\n              mode,\n              providers: asStringList(body?.providers),\n              models: asStringList(body?.models),\n              usedRounds: typeof body?.usedRounds === 'number' ? Math.max(0, Math.floor(body.usedRounds)) : 0,\n              usedTokens: typeof body?.usedTokens === 'number' ? Math.max(0, Math.floor(body.usedTokens)) : 0,\n              rating: ratingRaw,\n              note: note === '' ? undefined : note,\n            }\n            return withMeetingRpcLock(runtime, meetingId, async (stateRoot) => {\n              // 先清掉该会议的历史条目再追加（同一会议只保留最新一条反馈）。\n              await clearFeedbackForMeeting(stateRoot, meetingId)\n              await appendFeedback(stateRoot, entry)\n              return ok({ id: entry.id })\n            })\n          }\n          case 'roundtable/feedback.list': {\n            const body = payload as { workspace?: unknown } | undefined\n            const workspace = typeof body?.workspace === 'string' ? body.workspace : ''\n            const roots = await feedbackStateRoots(runtime, workspace)\n            const entries: FeedbackEntry[] = []\n            for (const stateRoot of roots) {\n              entries.push(...await readFeedback(stateRoot))\n            }\n            entries.sort((a, b) => b.ts - a.ts)\n            return ok({ entries: entries.slice(0, 200) })\n          }\n          case 'roundtable/feedback.clear': {\n            const body = payload as { workspace?: unknown } | undefined\n            const workspace = typeof body?.workspace === 'string' ? body.workspace : ''\n            const roots = await feedbackStateRoots(runtime, workspace)\n            let cleared = 0\n            for (const stateRoot of roots) {\n              cleared += await clearFeedback(stateRoot)\n            }\n            return ok({ cleared })\n          }\n          default:\n            return fail(`unknown endpoint: ${endpoint}`)\n        }\n    } catch (error: unknown) {\n      // HTTP 回退路由必须\"永不抛\"，否则 webServer 会以 400 收场、客户端只能\n      // 看到 fetch 失败而不是真正的错误信息。\n      return fail(error instanceof Error ? error.message : String(error))\n    }\n  }\n\n  // Transport 1: the host's generic connection channel (compatibility path).\n  // Two arguments only: the 0.1.1-era `{ authority: 'trusted-host' }` trust\n  // policy was removed from `connection.rpc.handle` —